import React, { useState } from 'react';

export const NotesPanel = () => {
  const [notes, setNotes] = useState('');

  const handleDownload = () => {
    if (!notes.trim()) {
      alert('No notes to download!');
      return;
    }

    const blob = new Blob([notes], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `saarthi-notes-${new Date().toISOString().slice(0, 10)}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="p-4 h-full flex flex-col">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-white font-semibold">Session Notes</h3>
        <button
          onClick={handleDownload}
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-2"
        >
          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
            <path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" />
          </svg>
          Download
        </button>
      </div>

      <textarea
        value={notes}
        onChange={(e) => setNotes(e.target.value)}
        placeholder="Take notes during your learning session..."
        className="flex-1 bg-gray-800 text-white rounded-lg p-4 focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
        style={{ minHeight: '500px' }}
      />

      <div className="mt-4 text-xs text-gray-400">
        <p>💡 Your notes are saved locally. Download to keep a permanent copy.</p>
      </div>
    </div>
  );
};
